#!/opt/anaconda3/bin/python
"""One fixed source-derived signed-distance composition, independent of zoom."""
import pathlib,json,hashlib,math,numpy as np
from scipy import ndimage
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'data/gameworld-v2';PAY=OUT/'payload';R=6371008.8

def save_array(name,a):
 p=PAY/name;a.tofile(p);return str(p.relative_to(ROOT))
def smoother(x):x=np.clip(x,0,1);return x*x*x*(x*(x*6-15)+10)
def phi(mask,sampling):return ndimage.distance_transform_edt(mask,sampling=sampling)-ndimage.distance_transform_edt(~mask,sampling=sampling)
def main():
 d=np.load(OUT/'source-observations/local-composition-inputs.npz');b=d['bounds'];raw=d['source_classes'];h,w=raw.shape;sx=(b[2]-b[0])*math.pi/180*R*math.cos(math.radians(41))/w;sy=(b[3]-b[1])*math.pi/180*R/h;xs=b[0]+(np.arange(w)+.5)*(b[2]-b[0])/w;ys=b[3]-(np.arange(h)+.5)*(b[3]-b[1])/h;collar=.03;wx=smoother((xs-b[0])/collar)*smoother((b[2]-xs)/collar);wy=smoother((ys-b[1])/collar)*smoother((b[3]-ys)/collar);weight=wy[:,None]*wx[None,:];gp=phi(d['global_water']>0,(sy,sx));np_=phi(d['native_water']>0,(sy,sx));combined=(1-weight)*gp+weight*np_;wet=combined>0;labels,count=ndimage.label(wet);sizes=np.bincount(labels.ravel());marine_seed=(d['global_water']==1)&((np.indices(wet.shape)[0]==0)|(np.indices(wet.shape)[0]==h-1)|(np.indices(wet.shape)[1]==0)|(np.indices(wet.shape)[1]==w-1));marine_ids=np.unique(labels[marine_seed&wet]);marine_ids=marine_ids[marine_ids>0];kind=np.where(wet,2,0).astype('u1');kind[np.isin(labels,marine_ids)]=1
 # Connected sourceocean expectedoneprimarycomponent; inner nativewater components retain source IDs.
 fg=phi(d['global_forest']>0,(sy,sx));fn=phi(d['native_forest']>0,(sy,sx));forest=((1-weight)*fg+weight*fn)>0;forest&=~wet;forest&=~np.isin(raw,[0,40,50]);classes=np.full((h,w),30,dtype='u1');classes[raw==0]=0;classes[forest]=10;classes[wet]=80;group,n=ndimage.label(forest);group=np.where(group>0,group+1000000,0).astype('<u4');interior=ndimage.distance_transform_edt(forest,sampling=(sy,sx)).astype('<f4');weights=np.zeros((h,w,4),dtype='u1');forest_phi=phi(forest,(sy,sx));weights[:,:,0]=np.rint(np.clip(.5+forest_phi/180,0,1)*255).astype('u1');weights[wet,0]=0;weights[:,:,2]=np.where(raw==60,255,0);weights[:,:,3]=np.rint(np.clip(1-np.abs(combined)/900,0,1)*255).astype('u1');weights[wet,3]=255
 signed=np.clip(combined,-3000,3000);code=np.rint((signed+4096)*8).astype('u2');packed=np.stack([code>>8,code&255],axis=2).astype('u1');mapping=[]
 for lab,sl in enumerate(ndimage.find_objects((group.astype('i8')-1000000).clip(0).astype('i4')),1):
  if sl is None:continue
  y,x=sl;mapping.append({'group_id':1000000+lab,'seed':int((117180+lab*2654435761)&0xffffffff),'source_bbox':[float(xs[x.start]),float(ys[y.stop-1]),float(xs[x.stop-1]),float(ys[y.start])],'source_model':'nativeESAtreecover with fixedspatial sourceconfidence collar, managedguard','edge_density':.42,'core_density':.88,'parent_regional_mapping':'same geographic coordinates; stablelocalIDnamespace1000000+'})
 for name,a in [('local-water.u8',kind),('local-forest-membership.u8',forest.astype('u1')),('local-classes.u8',classes),('local-forest-groups.u32',group),('local-forest-interior.f32',interior),('local-surface-weights.rgba8',weights),('local-distance.rg8',packed),('local-confidence.f32',weight.astype('<f4'))]:save_array(name,a)
 # Diagnostics report actualcomposition, not assuming role assignment fromclass80.
 info={'revision':'gameworld-v2-local-composition','bounds':dict(zip(['west','south','east','north'],b.tolist())),'width':w,'height':h,'inner_confidence_bounds':[float(b[0]+collar),float(b[1]+collar),float(b[2]-collar),float(b[3]-collar)],'marine_components':len(marine_ids),'marine_component_pixel_counts':[int(sizes[x]) for x in marine_ids],'inland_components':count-len(marine_ids),'forest_groups':n,'group_mapping':mapping,'source_guard_failures':int(np.count_nonzero(np.isin(raw,[0,40,50])&forest)),'forest_water_overlap':int(np.count_nonzero(wet&forest)),'method':'C2product spatialconfidence signed-distance sourcefusion; fixed canonical coastline, independentofzoom. Outerboundary inheritsregionalphysicalwater; largestconnectedseaseededcomponents aremarine, remainingpositiveareas inlandwater. No rolesnumericallyblended.','sdf_representation':'signeddistance sourcefusion field sampledfromcanonicalpolygon rasterizations; encodedRG8-.125step; finalglobalpolygonregeneration to follow'};(OUT/'local-composition.json').write_text(json.dumps(info,indent=2)+'\n');print('local composition done marine',len(marine_ids),'lakes',count-len(marine_ids),'groups',n,flush=True)
if __name__=='__main__':main()
